package com.witchersbestiary.test;
import com.witchersbestiary.contracts.*;
import com.witchersbestiary.contracts.hunt.*;
import com.witchersbestiary.contracts.procedural.*;
import com.witchersbestiary.contracts.tracking.*;
import net.fabricmc.fabric.api.gametest.v1.FabricGameTest;
import net.minecraft.block.Blocks;
import net.minecraft.entity.*;
import net.minecraft.entity.mob.MobEntity;
import net.minecraft.nbt.*;
import net.minecraft.registry.*;
import net.minecraft.test.*;
import net.minecraft.util.Identifier;
import net.minecraft.util.math.*;
import java.util.*;
public final class InvestigationTests implements FabricGameTest {
 private static final String ARENA="witchersbestiary:village_board_arena";
 private BlockPos field(TestContext c){for(int x=0;x<48;x++)for(int z=0;z<48;z++){c.setBlockState(new BlockPos(x,1,z),Blocks.GRASS_BLOCK);for(int y=2;y<14;y++){var q=c.getAbsolutePos(new BlockPos(x,y,z));if(c.getWorld().getBlockState(q).isOf(Blocks.BARRIER))c.getWorld().setBlockState(q,Blocks.AIR.getDefaultState());}}var at=c.getAbsolutePos(new BlockPos(35,2,24));var w=c.getWorld();var forest=w.getRegistryManager().get(RegistryKeys.BIOME).getEntry(net.minecraft.world.biome.BiomeKeys.FOREST).orElseThrow();for(int x=0;x<4;x++)for(int z=0;z<4;z++){var origin=c.getAbsolutePos(BlockPos.ORIGIN);var chunk=w.getChunkManager().getWorldChunk((origin.getX()>>4)+x,(origin.getZ()>>4)+z);if(chunk!=null)chunk.populateBiomes((a,b,d,s)->forest,w.getChunkManager().getNoiseConfig().getMultiNoiseSampler());}w.setBlockState(at.add(0,-1,2),Blocks.WATER.getDefaultState());return at;}
 private net.minecraft.server.network.ServerPlayerEntity player(TestContext c,BlockPos at){var p=c.createMockCreativeServerPlayerInWorld();p.teleport(c.getWorld(),at.getX()-33,at.getY(),at.getZ(),0,0);return p;}
 private void approach(net.minecraft.server.network.ServerPlayerEntity p,ContractClue clue){p.refreshPositionAndAngles(clue.position.getX()+.5,clue.position.getY(),clue.position.getZ()-2,0,35);}
 private void reject(TestContext c,Runnable r){boolean no=false;try{r.run();}catch(IllegalStateException e){no=true;}c.assertTrue(no,"Rejected operation");}
 @GameTest(templateName=ARENA,batchId="investigation",tickLimit=40)
 public void routeSafetyTypesLinksAndNoEarlyTarget(TestContext c){var at=field(c);var p=player(c,at);var instance=Contracts.assign(p,GraveDevourer.ID);c.assertTrue(Investigations.prepare(p,instance,at),"Prepare through existing territory result");var i=instance.investigation;c.assertTrue(i.stage==ContractInvestigation.Stage.TRACKING&&i.clues.size()==2&&instance.hunt.target==null,"Bounded route before physical target");var ids=new HashSet<UUID>();for(int n=0;n<i.clues.size();n++){var clue=i.clues.get(n);c.assertTrue(ids.add(clue.id)&&clue.order==n&&clue.owner.equals(p.getUuid())&&clue.contract.equals(instance.id())&&Investigations.safeClue(c.getWorld(),clue.position),"Safe owned ordered clue");c.assertTrue(Objects.equals(clue.next,n+1<i.clues.size()?i.clues.get(n+1).id:null),"Next link");}c.assertTrue(!Investigations.safeClue(c.getWorld(),at.up(4)),"Air rejected");c.getWorld().setBlockState(at,Blocks.STONE.getDefaultState());c.assertTrue(!Investigations.safeClue(c.getWorld(),at),"Inside block rejected");c.assertTrue(!Investigations.safeClue(c.getWorld(),new BlockPos(20000000,at.getY(),20000000)),"Unloaded region rejected");c.assertTrue(c.getWorld().getChunkManager().getWorldChunk(20000000>>4,20000000>>4)==null,"No chunk forced");Contracts.cancel(p,instance.id());p.discard();c.complete();}
 @GameTest(templateName=ARENA,batchId="investigation",tickLimit=40)
 public void ownershipDistanceOrderReplayAndDimension(TestContext c){var at=field(c);var p=player(c,at);var other=player(c,at);var instance=Contracts.assign(p,GraveDevourer.ID);Investigations.prepare(p,instance,at);var first=instance.investigation.next();approach(other,first);c.assertTrue(!Investigations.inspect(other,first.id),"Foreign owner cannot study");p.refreshPositionAndAngles(first.position.getX()+40,first.position.getY(),first.position.getZ(),0,0);c.assertTrue(!Investigations.inspect(p,first.id),"Remote request rejected");approach(p,first);c.assertTrue(!Investigations.inspect(p,instance.investigation.clues.getLast().id),"Out of order request rejected");Investigations.toggle(p,true);c.assertTrue(Investigations.view(p).has("point"),"Own nearby clue only");var world=p.getServerWorld();p.setServerWorld(p.getServer().getWorld(net.minecraft.world.World.NETHER));c.assertTrue(!Investigations.inspect(p,first.id)&&!Investigations.view(p).has("point")&&!Investigations.enabled(p.getUuid()),"Dimension change disables effects and denies study");p.setServerWorld(world);approach(p,first);c.assertTrue(Investigations.inspect(p,first.id)&&!Investigations.inspect(p,first.id),"Study once");c.assertTrue(instance.investigation.current==1&&first.studied,"Progress once");Contracts.cancel(p,instance.id());c.assertTrue(!Investigations.inspect(p,instance.investigation.next().id),"Cancelled investigation denied");p.discard();other.discard();c.complete();}
 @GameTest(templateName=ARENA,batchId="investigation",tickLimit=40)
 public void diskProgressLogoutAndNoRouteRegeneration(TestContext c){var at=field(c);var p=player(c,at);var instance=Contracts.assign(p,ProceduralHunts.id("foglet"));Investigations.prepare(p,instance,at);var first=instance.investigation.next();approach(p,first);Investigations.inspect(p,first.id);var saved=instance.toNbt();try{var file=java.nio.file.Files.createTempFile(java.nio.file.Path.of("."),"investigation-",".nbt");NbtIo.writeCompressed(saved,file);saved=NbtIo.readCompressed(file,NbtSizeTracker.ofUnlimitedBytes());java.nio.file.Files.delete(file);}catch(java.io.IOException e){throw new RuntimeException(e);}var copy=ContractInstance.fromNbt(saved);c.assertTrue(copy.investigation.current==1&&copy.investigation.clues.getFirst().id.equals(first.id)&&copy.investigation.lair.equals(at),"Disk route/progress/lair persistence");var route=instance.investigation;Investigations.prepare(p,instance,at.add(6,0,0));c.assertTrue(route==instance.investigation,"Prepare cannot regenerate an existing route");Investigations.toggle(p,true);Investigations.disconnected(p.getUuid());c.assertTrue(!Investigations.enabled(p.getUuid())&&instance.investigation==route&&instance.hunt.target==null,"Logout clears only local session");var ids=route.clues.stream().map(clue->clue.id).toList();c.assertTrue(new HashSet<>(ids).size()==ids.size(),"No duplicate IDs");Contracts.cancel(p,instance.id());p.discard();c.complete();}
 @GameTest(templateName=ARENA,batchId="investigation",tickLimit=40)
 public void allFiveHuntsLairSpawnCompletionAndReward(TestContext c){var at=field(c);var p=player(c,at);for(var id:List.of(ProceduralHunts.id("drowner"),ProceduralHunts.id("ghoul"),ProceduralHunts.id("foglet"),SwampLord.ID,GraveDevourer.ID)){p.refreshPositionAndAngles(at.getX()-33,at.getY(),at.getZ(),0,0);var instance=Contracts.assign(p,id);c.assertTrue(Investigations.prepare(p,instance,at),"Territory route "+id);var i=instance.investigation;var clues=i.clues;for(int n=0;n<clues.size();n++){c.assertTrue(instance.hunt.target==null,"No physical target before final clue");approach(p,clues.get(n));c.assertTrue(Investigations.inspect(p,clues.get(n).id),"Sequential study "+n);}c.assertTrue(i.stage==ContractInvestigation.Stage.LAIR_FOUND&&instance.hunt.target==null,"Separate lair stage after two clues");p.refreshPositionAndAngles(at.getX()+.5,at.getY(),at.getZ()+.5,0,0);Investigations.trySpawn(p,instance);c.assertTrue(i.stage==ContractInvestigation.Stage.HUNTING&&instance.hunt.target!=null,"Lair creates existing unique target");UUID uuid=instance.hunt.target;c.assertTrue(!Investigations.trySpawn(p,instance)&&!SwampLord.spawn(p,instance,at),"No duplicate target");var boss=(MobEntity)c.getWorld().getEntity(uuid);c.assertTrue(boss!=null,"Physical bound target");boss.setAiDisabled(true);boss.damage(c.getWorld().getDamageSources().genericKill(),10000);c.assertTrue(instance.status()==ContractInstance.Status.COMPLETED&&i.stage==ContractInvestigation.Stage.COMPLETED,"Bound death completes both lifecycles");Contracts.claim(p,instance.id());reject(c,()->Contracts.claim(p,instance.id()));c.assertTrue(!Investigations.inspect(p,clues.getLast().id),"No late clue replay or reward");boss.discard();}p.discard();c.complete();}
 @GameTest(templateName=ARENA,batchId="investigation",tickLimit=40)
 public void oneFiveTenPrivateInvestigationsAndFallback(TestContext c){var at=field(c);var players=new ArrayList<net.minecraft.server.network.ServerPlayerEntity>();var instances=new ArrayList<ContractInstance>();for(int n=0;n<10;n++){var p=player(c,at);players.add(p);var instance=Contracts.assign(p,GraveDevourer.ID);instances.add(instance);Investigations.prepare(p,instance,at);approach(p,instance.investigation.next());Investigations.toggle(p,true);}
  for(int count:new int[]{1,5,10}){long start=System.nanoTime();for(int tick=0;tick<100;tick++)for(int n=0;n<count;n++){var view=Investigations.view(players.get(n));c.assertTrue(view.getAsJsonObject("point").get("id").getAsString().equals(instances.get(n).investigation.next().id.toString()),"Only private current point");}System.out.println("INVESTIGATION_SUBSYSTEM owners="+count+" avg_view_batch_ns="+(System.nanoTime()-start)/100+" (manual snapshot query, not server TPS/MSPT)");}
  for(int n=0;n<10;n++){c.assertTrue(instances.get(n).hunt.target==null,"No entities for clues");Contracts.cancel(players.get(n),instances.get(n).id());players.get(n).discard();}var bounded=new InvestigationSettings(-2,99,4,5,100);c.assertTrue(bounded.common()==1&&bounded.rare()==5&&bounded.radius()==32,"Configuration bounds");for(int x=0;x<34;x++)for(int z=0;z<48;z++)c.setBlockState(new BlockPos(x,1,z),Blocks.GLASS);var fallbackPlayer=player(c,at);var fallback=Contracts.assign(fallbackPlayer,GraveDevourer.ID);c.assertTrue(!Investigations.prepare(fallbackPlayer,fallback,at)&&fallback.investigation.stage==ContractInvestigation.Stage.SEARCHING,"Unsafe two-clue route waits without losing identity");Contracts.cancel(fallbackPlayer,fallback.id());fallbackPlayer.discard();c.complete();}
 @GameTest(templateName=ARENA,batchId="investigation",tickLimit=40)
 public void legacyDirectTargetRemainsFinishable(TestContext c){var at=field(c);var p=player(c,at);var instance=Contracts.assign(p,GraveDevourer.ID);instance.investigation=null;c.assertTrue(SwampLord.spawn(p,instance,at),"Legacy target without investigation supported");var boss=(MobEntity)c.getWorld().getEntity(instance.hunt.target);boss.damage(c.getWorld().getDamageSources().genericKill(),10000);c.assertTrue(instance.status()==ContractInstance.Status.COMPLETED,"Legacy death not blocked by missing route");Contracts.claim(p,instance.id());p.discard();c.complete();}
}
